package com.hbm.machine.foundry.crucible.client;
import com.hbm.recipe.generic.Blueprints;
import com.hbm.client.gui.LegacyContainerScreen;
import com.hbm.client.recipe.generic.GenericRecipeSelectorScreen;
import com.hbm.machine.foundry.crucible.*;
import com.hbm.material.*;
import com.mojang.blaze3d.platform.GlStateManager;
import com.mojang.blaze3d.systems.RenderSystem;
import java.util.*;
import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.network.chat.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.network.PacketDistributor;
/** Original 176x168 firebox and 176x214 crucible GUIs, original quanta columns and selector. */
public final class ThermalScreen extends LegacyContainerScreen<ThermalMenu> {
 public ThermalScreen(ThermalMenu menu,Inventory inventory,Component title){super(menu,inventory,title,ResourceLocation.fromNamespaceAndPath("hbm",menu.firebox?"textures/gui/machine/gui_firebox.png":"textures/gui/processing/gui_crucible.png"),176,menu.firebox?168:214);}
 private ThermalMachine machine(){return minecraft.level.getBlockEntity(menu.position()) instanceof ThermalMachine be?be:null;}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,title,(imageWidth-font.width(title))/2,6,menu.firebox?0x404040:0xffffff,false);g.drawString(font,playerInventoryTitle,8,imageHeight-94,0x404040,false);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){super.renderBg(g,partial,x,y);var be=machine();if(be instanceof FireboxBlockEntity b){drawLegacyRegion(g,81,28,176,0,b.heatEnergy*69/CrucibleConfig.fireboxMaxHeat,5);drawLegacyRegion(g,81,37,176,5,b.burnTime*70/Math.max(1,b.maxBurnTime),5);if(b.wasOn)drawLegacyRegion(g,25,26,176,10,18,18);}else if(be instanceof CrucibleBlockEntity b){int p=b.progress*33/CrucibleConfig.processHeat,h=b.heat*33/CrucibleConfig.maxHeat;if(p>0)drawLegacyRegion(g,126,82,176,0,p,5);if(h>0)drawLegacyRegion(g,126,91,176,5,h,5);var recipe=b.loadedRecipe();g.renderItem(recipe==null?new ItemStack(Blueprints.FOLDER.get()):recipe.icon(),leftPos+107,topPos+81);column(g,b.recipeStack,CrucibleConfig.recipeCapacity,62,97);column(g,b.wasteStack,CrucibleConfig.wasteCapacity,17,97);}}
 private void column(GuiGraphics g,List<MaterialStack> list,int capacity,int x,int y){int height=0,quant=0;for(var stack:list){int target=(quant+stack.amount)*79/capacity;if(target==height)continue;int u=176+(stack.material.smeltingBehavior()==NtmMaterial.SmeltingBehavior.ADDITIVE?34:0),rgb=stack.material.moltenColor();g.setColor((rgb>>16&255)/255F,(rgb>>8&255)/255F,(rgb&255)/255F,1);drawLegacyRegion(g,x,y-target,u,89-target,34,target-height);g.flush();RenderSystem.enableBlend();RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA,GlStateManager.DestFactor.ONE);g.setColor(1,1,1,.3F);drawLegacyRegion(g,x,y-target,u,89-target,34,target-height);g.flush();RenderSystem.disableBlend();quant+=stack.amount;height=target;}RenderSystem.defaultBlendFunc();g.setColor(1,1,1,1);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);var be=machine();if(be instanceof FireboxBlockEntity b){if(legacyInfoHovered(x,y,80,27,71,7))g.renderTooltip(font,tu(b.heatEnergy,CrucibleConfig.fireboxMaxHeat),x,y);if(legacyInfoHovered(x,y,80,36,71,7))g.renderComponentTooltip(font,List.of(Component.literal(b.burnHeat+"TU/t"),Component.literal(b.burnTime/20+"s")),x,y);if(menu.getCarried().isEmpty())for(int i=0;i<2;i++){var slot=menu.getSlot(i);if(!slot.hasItem()&&legacyInfoHovered(x,y,slot.x,slot.y,16,16)){var lines=bonuses();if(!lines.isEmpty())g.renderComponentTooltip(font,lines,x,y);}}}else if(be instanceof CrucibleBlockEntity b){if(legacyInfoHovered(x,y,16,17,36,81))materialInfo(g,b.wasteStack,x,y);if(legacyInfoHovered(x,y,61,17,36,81))materialInfo(g,b.recipeStack,x,y);if(legacyInfoHovered(x,y,125,81,34,7))g.renderTooltip(font,tu(b.progress,CrucibleConfig.processHeat),x,y);if(legacyInfoHovered(x,y,125,90,34,7))g.renderTooltip(font,tu(b.heat,CrucibleConfig.maxHeat),x,y);if(legacyInfoHovered(x,y,106,80,18,18)){var recipe=b.loadedRecipe();g.renderComponentTooltip(font,recipe==null?List.of(Component.translatable("gui.recipe.setRecipe").withStyle(ChatFormatting.YELLOW)):recipe.tooltip(),x,y);}}}
 private static Component tu(int value,int maximum){return Component.literal(String.format(Locale.US,"%,d / %,dTU",value,maximum));}
 private void materialInfo(GuiGraphics g,List<MaterialStack> stacks,int x,int y){var lines=new ArrayList<Component>();if(stacks.isEmpty())lines.add(Component.translatable("gui.hbm.crucible.empty").withStyle(ChatFormatting.RED));for(var stack:stacks)lines.add(stack.material.displayName().copy().append(": ").append(HbmMaterials.formatAmount(stack.amount,hasShiftDown())).withStyle(ChatFormatting.YELLOW));g.renderComponentTooltip(font,lines,x,y);}
 private static List<Component> bonuses(){var lines=new ArrayList<Component>();double[][] mods={CrucibleConfig.BURN.getModTime(),CrucibleConfig.BURN.getModHeat()};for(int type=0;type<2;type++){var section=new ArrayList<Component>();for(int i=0;i<8;i++)if(mods[type][i]!=1){int percent=(int)((mods[type][i]-1)*100);section.add(Component.literal("- ").append(Component.translatable("gui.hbm.firebox.fuel."+i)).append(": ").withStyle(ChatFormatting.YELLOW).append(Component.literal((percent>=0?"+":"")+percent+"%").withStyle(percent>=0?ChatFormatting.GREEN:ChatFormatting.RED)));}if(!section.isEmpty()){lines.add(Component.translatable(type==0?"gui.hbm.firebox.time_bonus":"gui.hbm.firebox.heat_bonus").withStyle(type==0?ChatFormatting.GOLD:ChatFormatting.RED));lines.addAll(section);}}return lines;}
 @Override public boolean mouseClicked(double x,double y,int button){boolean handled=super.mouseClicked(x,y,button);if(!menu.firebox&&legacyInfoHovered(x,y,106,80,18,18)&&machine() instanceof CrucibleBlockEntity b){GenericRecipeSelectorScreen.open(b.recipes(),b.recipe,null,this,selection->PacketDistributor.sendToServer(new CrucibleSelection(menu.containerId,selection)));return true;}return handled;}
}
